   [64]={next_id=65, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我选择带着大家从约瑟伯格回来，就做好了这样的心理准备。", msg_color="", msg_size=0, talker="弗丽达", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7143", 2, 0, 31, 178},{ 3, "7187", 0, 0, 39, 202.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
